<main class="boon-ops" :data-page="pageKey" data-testid="shopping-store-operation-page"><header class="boon-opbar"><button @click="emit('back')">←</button><strong>BOONTHESHOP</strong><div><button data-testid="shopping-open-service" @click="emit('open-service')">ATELIER</button><button @click="emit('open-orders')">APPOINTMENTS</button><button @click="emit('open-cart')">FITTING LIST <b v-if="cartQuantity">{{ cartQuantity }}</b></button></div></header>
